const BlockEmbed = Quill.import('blots/block/embed');

const ATTRIBUTES = ['alt', 'height', 'width'];

function sanitize(url: any, protocols: any): any {
  const anchor = document.createElement('a');
  anchor.href = url;
  const protocol = anchor.href.slice(0, anchor.href.indexOf(':'));
  return protocols.indexOf(protocol) > -1;
}

export class ImageBlot extends BlockEmbed {
  static create(value: any): any {
    const node = super.create(value);
    if (typeof value === 'string') {
      node.setAttribute('src', this.sanitize(value));
    }
    return node;
  }

  static formats(domNode: any): any {
    return ATTRIBUTES.reduce(function (formats: any, attribute: any): any {
      if (domNode.hasAttribute(attribute)) {
        formats[attribute] = domNode.getAttribute(attribute);
      }
      return formats;
    }, {});
  }

  static match(url: any): any {
    return /\.(jpe?g|gif|png)$/.test(url) || /^data:image\/.+;base64/.test(url);
  }

  static sanitize(url: any): any {
    return sanitize(url, ['http', 'https', 'data']) ? url : '//:0';
  }

  static value(domNode: any): any {
    return domNode.getAttribute('src');
  }

  format(name: any, value: any): any {
    if (ATTRIBUTES.indexOf(name) > -1) {
      if (value) {
        this.domNode.setAttribute(name, value);
      } else {
        this.domNode.removeAttribute(name);
      }
    } else {
      super.format(name, value);
    }
  }
}
ImageBlot.blotName = 'image';
ImageBlot.tagName = 'img';
