  constructor() {
    super();
  }

  public atualizaQuantidadeRevisao = (quantidade: number): void => {
    this.quantidadeRevisao = quantidade;
  };

  private onToggle(ev: Event): void {
    const target = ev.currentTarget as any;
    const next = !!target?.checked;

    ev.stopImmediatePropagation?.();
    ev.stopPropagation();
    ev.preventDefault();

    this.dispatchEvent(
      new CustomEvent('switch-revisao:intent', {
        bubbles: true,
        composed: true,
        detail: { checked: next },
      }),
    );

    queueMicrotask(() => {
      if (target) {
        target.checked = this.checked;
        target.requestUpdate?.();
      }
    });
  }

  public setChecked(value: boolean): void {
    this._programmatic = true;
    this.checked = !!value;
    const sw = this.querySelector(`#${this.nomeSwitch}`) as any;
    if (sw) {
      sw.checked = this.checked;
      sw.requestUpdate?.();
    }
    this.requestUpdate();
    this._programmatic = false;
  }

